"use client";

import { useId, useRef, useState } from "react";
import "./expanding-action-group.css";

export interface ExpandingAction {
  id: string;
  label: string;
}

export interface ExpandingActionGroupProps {
  actions: ExpandingAction[];
  label?: string;
  onAction: (id: string) => void;
}

export function ExpandingActionGroup({
  actions,
  label = "More actions",
  onAction,
}: ExpandingActionGroupProps) {
  const [open, setOpen] = useState(false);
  const panelId = useId();
  const triggerRef = useRef<HTMLButtonElement>(null);

  function close() {
    setOpen(false);
    triggerRef.current?.focus();
  }

  return (
    <div
      className="tb-action-group"
      data-open={open}
      onKeyDown={(event) => {
        if (event.key === "Escape" && open) {
          event.preventDefault();
          close();
        }
      }}
    >
      <button
        aria-controls={panelId}
        aria-expanded={open}
        className="tb-action-group__trigger"
        disabled={!actions.length}
        onClick={() => setOpen((value) => !value)}
        ref={triggerRef}
        type="button"
      >
        <span>{label}</span>
        <span className="tb-action-group__mark" aria-hidden="true" />
      </button>
      {open ? (
        <div
          className="tb-action-group__panel"
          id={panelId}
          role="group"
          aria-label={label}
        >
          {actions.map((action) => (
            <button
              className="tb-action-group__action"
              key={action.id}
              onClick={() => {
                onAction(action.id);
                close();
              }}
              type="button"
            >
              {action.label}
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
}

.tb-action-group {
  display: inline-grid;
  width: fit-content;
  max-width: min(100%, 52rem);
  color: #f4f5ee;
  border: 1px solid #f4f5ee;
  background: #121514;
}

.tb-action-group[data-open="true"] {
  grid-template-columns: minmax(0, 0.45fr) minmax(0, 1fr);
  width: min(100%, 52rem);
}

.tb-action-group button {
  appearance: none;
  min-height: 3.35rem;
  color: inherit;
  border: 0;
  background: transparent;
  font: 650 0.82rem/1 system-ui, sans-serif;
  overflow-wrap: anywhere;
  white-space: normal;
  cursor: pointer;
  touch-action: manipulation;
}

.tb-action-group__trigger {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.6rem;
  min-width: min(10.5rem, 100%);
  padding: 0 1rem;
  text-align: left;
}

.tb-action-group__mark {
  position: relative;
  width: 0.9rem;
  height: 0.9rem;
}

.tb-action-group__mark::before,
.tb-action-group__mark::after {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0.9rem;
  height: 1px;
  background: currentColor;
  content: "";
  transform: translate(-50%, -50%);
  transition: transform 150ms ease-out;
}

.tb-action-group__mark::after {
  transform: translate(-50%, -50%) rotate(90deg);
}

.tb-action-group[data-open="true"] .tb-action-group__mark::after {
  transform: translate(-50%, -50%) rotate(0deg);
}

.tb-action-group__panel {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(8.5rem, 100%), 1fr));
  gap: 1px;
  min-width: 0;
  border-left: 1px solid #555b57;
  background: #303532;
  animation: tb-action-group-enter 160ms ease-out both;
}

.tb-action-group .tb-action-group__action {
  padding: 0 1rem;
  background: #121514;
}

@media (hover: hover) and (pointer: fine) {
  .tb-action-group button:hover {
    color: #d6ff55;
    background: #222724;
  }
}

.tb-action-group button:active {
  background: #303630;
}

.tb-action-group button:disabled {
  color: #9b9e9b;
  cursor: not-allowed;
}

.tb-action-group button:focus-visible {
  position: relative;
  z-index: 1;
  outline: 3px solid #d6ff55;
  outline-offset: -5px;
}

@keyframes tb-action-group-enter {
  from {
    opacity: 0;
    transform: translateX(-0.45rem);
  }
}

@media (max-width: 34rem) {
  .tb-action-group {
    width: 100%;
  }

  .tb-action-group[data-open="true"] {
    grid-template-columns: 1fr;
  }

  .tb-action-group__panel {
    border-top: 1px solid #555b57;
    border-left: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tb-action-group__mark::before,
  .tb-action-group__mark::after {
    transition: none;
  }

  .tb-action-group__panel {
    animation: none;
  }
}

@media (forced-colors: active) {
  .tb-action-group,
  .tb-action-group__panel,
  .tb-action-group .tb-action-group__action {
    border-color: ButtonText;
  }
}
